static DNSData* SetNewDNSData(Packet* p, bool udp)
{
    DnsFlowData* fd;

    if (udp)
        return nullptr;

    fd = new DnsFlowData;
    fd->session.dns_events.set_packet(p);
    p->flow->set_flow_data(fd);

    return &fd->session;
}

bool DNSData::valid_dns(const DNSHdr& dns_header)
{
    // Check QR bit (Query/Response)
    bool is_query = ((dns_header.flags & 0x8000) == 0);

    // Check Opcode (should be 0 for standard queries)
    uint16_t opcode = (dns_header.flags & 0x7800) >> 11;
    if (opcode > 2) 
        return false;

    // Check for reserved bits and RCODE
    if (dns_header.flags & 0x7800)
        return false;

    // Validate Recursion bits (RA should not be set in a query)
    bool ra_bit = (dns_header.flags & 0x0080) != 0;
    if (is_query && ra_bit) 
        return false;

    return true;
}

DNSData* get_dns_session_data(Packet* p, bool from_server, DNSData& udpSessionData, bool udp)
{
    DnsFlowData* fd;
    if (udp)
    {
        if(p->dsize > MAX_UDP_PAYLOAD)
            return nullptr;

        if(!from_server)
        {
            if (p->dsize < (sizeof(DNSHdr) + sizeof(DNSQuestion) + 2))
                return nullptr;
        }
        else
        {
            if (p->dsize < (sizeof(DNSHdr)))
                return nullptr;
        }
        udpSessionData.dns_events.set_packet(p);
        return &udpSessionData;
    }

    fd = static_cast<DnsFlowData*>((p->flow)->get_flow_data(DnsFlowData::inspector_id));
    if (fd)
    {
        fd->session.dns_events.set_packet(p);
        return &fd->session;
    }
    return nullptr;
}

