using namespace snort;

StreamSplitter::Status DnsSplitter::scan(
    Packet* p, const uint8_t* data, uint32_t len,
    uint32_t, uint32_t* fp)
{
    assert(len > 0);

    const DnsFlowData* fd;
    fd = static_cast<DnsFlowData*>(p->flow->get_flow_data(DnsFlowData::inspector_id));
    if (fd && (fd->session.flags & DNS_FLAG_NOT_DNS))
    {
        dnsstats.aborted_sessions++;
        return ABORT;
    }

    if ( partial )
    {
        uint32_t msg_len = size + *data;

        if ( msg_len < DNS_SPLITTER_MIN_USEFUL_LENGTH
            and ++tiny_msg_count > DNS_SPLITTER_MAX_TINY_MSGS )
        {
            dnsstats.aborted_sessions++;
            return ABORT;
        }

        *fp = msg_len + 1;
        partial = false;
        return FLUSH;
    }

    if ( len == 1 )
    {
        size = *data << 8;
        partial = true;
        return SEARCH;
    }

    uint32_t msg_len = (*data << 8) + data[1];

    if ( msg_len < DNS_SPLITTER_MIN_USEFUL_LENGTH
        and ++tiny_msg_count > DNS_SPLITTER_MAX_TINY_MSGS )
    {
        dnsstats.aborted_sessions++;
        return ABORT;
    }

    *fp = msg_len + 2;
    return FLUSH;
}

