    using Base = EventGen<HttpEnums::EVENT__MAX_VALUE, HttpEnums::EVENT__NONE,
        HttpEnums::HTTP_GID>;
    using Base::Base;

    bool create_event_if_new(int sid)
    {
        if (sid == HttpEnums::EVENT__NONE)
            return false;
        assert((sid > 0) && (sid <= HttpEnums::EVENT__MAX_VALUE));
        if (events_suppressed[sid-1])
