{
public:
    ScopedSocksUdpRebuild()
    { ++socks_udp_rebuild_depth; }

    ~ScopedSocksUdpRebuild()
    {
        assert(socks_udp_rebuild_depth);
        --socks_udp_rebuild_depth;
    }

