    72	bool media_type_matches(std::string_view value, const std::string& expected)
    73	{
    74	    while (!value.empty() and is_ascii_space(value.front()))
    75	        value.remove_prefix(1);
    76	    while (!value.empty() and is_ascii_space(value.back()))
    77	        value.remove_suffix(1);
    78	
    79	    const size_t parameter = value.find(';');
    80	    if (parameter != std::string_view::npos)
    81	        value = value.substr(0, parameter);
    82	
    83	    while (!value.empty() and is_ascii_space(value.back()))
    84	        value.remove_suffix(1);
    85	
    86	    if (value.size() != expected.size())
    87	        return false;
    88	
    89	    return std::equal(value.begin(), value.end(), expected.begin(),
    90	        [](char lhs, char rhs)
    91	        {
    92	            return std::tolower(static_cast<unsigned char>(lhs)) ==
    93	                std::tolower(static_cast<unsigned char>(rhs));
    94	        });
    95	}
