    97	bool find_dns_query_param(std::string_view query, std::string& encoded_query)
    98	{
    99	    encoded_query.clear();
   100	
   101	    size_t offset = 0;
   102	    while (offset <= query.size())
   103	    {
   104	        size_t end = query.find('&', offset);
   105	        if (end == std::string_view::npos)
   106	            end = query.size();
   107	
   108	        const std::string_view parameter = query.substr(offset, end - offset);
   109	        const size_t equal = parameter.find('=');
   110	        if (equal != std::string_view::npos and parameter.substr(0, equal) == "dns")
   111	        {
   112	            encoded_query.assign(parameter.substr(equal + 1));
   113	            return !encoded_query.empty();
   114	        }
   115	
   116	        if (end == query.size())
   117	            break;
   118	        offset = end + 1;
   119	    }
   120	
   121	    return false;
   122	}
