124	static int base64_value(char c)
125	{
126	    if (c >= 'A' and c <= 'Z')
127	        return c - 'A';
128	    if (c >= 'a' and c <= 'z')
129	        return c - 'a' + 26;
130	    if (c >= '0' and c <= '9')
131	        return c - '0' + 52;
132	    if (c == '+' or c == '-')
133	        return 62;
134	    if (c == '/' or c == '_')
135	        return 63;
136	    return -1;
137	}
