   205	void DohInspector::process_request_header(DataEvent& event, Flow* flow)
   206	{
   207	    Profile profile(doh_perf_stats);
   208	
   209	    auto* http_event = static_cast<HttpEvent*>(&event);
   210	
   211	    int32_t uri_length = 0;
   212	    const uint8_t* uri = http_event->get_uri(uri_length);
   213	    if (!uri or uri_length <= 0)
   214	        return;
   215	
   216	    doh::UriParts parts;
   217	    if (!doh::split_uri(std::string_view(reinterpret_cast<const char*>(uri),
   218	        static_cast<size_t>(uri_length)), parts))
   219	        return;
   220	
   221	    const bool path_match = path_matches(config, parts.path);
   222	
   223	    int32_t content_type_length = 0;
   224	    const uint8_t* content_type = http_event->get_content_type(content_type_length);
   225	    const bool content_type_match =
   226	        content_type_matches(config, content_type, content_type_length);
   227	
   228	    std::string encoded_query;
   229	    const bool has_query = doh::find_dns_query_param(parts.query, encoded_query);
   230	
   231	    if (!path_match and !content_type_match)
   232	        return;
   233	
   234	    DohTransactionState* transaction =
   235	        get_transaction(flow, http_event->get_httpx_stream_id());
   236	    if (!transaction)
   237	        return;
   238	
   239	    if (transaction->request_seen)
   240	        return;
   241	
   242	    int32_t method_length = 0;
   243	    const uint8_t* method = http_event->get_method(method_length);
   244	    transaction->method = to_string(method, method_length);
   245	    transaction->path = parts.path;
   246	    transaction->content_type = to_string(content_type, content_type_length);
   247	    transaction->request_seen = true;
   248	    transaction->request_is_doh =
   249	        (path_match and (content_type_match or has_query)) or content_type_match;
   250	
   251	    if (!transaction->request_is_doh)
   252	        return;
   253	
   254	    doh_stats.requests++;
   255	    if (transaction->method == "GET")
   256	        doh_stats.get_requests++;
   257	    else if (transaction->method == "POST")
   258	        doh_stats.post_requests++;
   259	
   260	    if (!has_query)
   261	        return;
   262	
   263	    std::vector<uint8_t> decoded;
   264	    if (!doh::base64url_decode(encoded_query, decoded))
   265	    {
   266	        doh_stats.malformed_queries++;
   267	        return;
   268	    }
   269	
   270	    doh::DnsQuestion question;
   271	    const doh::ParseStatus status =
   272	        doh::parse_dns_question(decoded.data(), decoded.size(), question);
   273	    if (status != doh::ParseStatus::OK)
   274	    {
   275	        doh_stats.malformed_queries++;
   276	        return;
   277	    }
   278	
   279	    record_domain(*transaction, question, true, flow);
   280	}
