   304	void DohInspector::process_body(DataEvent& event, Flow* flow)
   305	{
   306	    Profile profile(doh_perf_stats);
   307	
   308	    auto* body_event = static_cast<HttpDohBodyEvent*>(&event);
   309	
   310	    int32_t length = 0;
   311	    const uint8_t* data = body_event->get_body(length);
   312	    if (!data or length <= 0)
   313	        return;
   314	
   315	    DohTransactionState* transaction =
   316	        get_transaction(flow, body_event->get_httpx_stream_id());
   317	    if (!transaction)
   318	        return;
   319	
   320	    const bool from_client = body_event->is_data_from_client();
   321	    if (from_client)
   322	    {
   323	        if (!transaction->request_is_doh)
   324	            return;
   325	        append_body(transaction->request_body, data, length);
   326	        if (!transaction->request_domain_recorded)
   327	            parse_query_payload(*transaction, transaction->request_body.data(),
   328	                transaction->request_body.size(), true, body_event->is_last_piece(), flow);
   329	    }
   330	    else
   331	    {
   332	        if (!transaction->response_is_doh)
   333	            return;
   334	        append_body(transaction->response_body, data, length);
   335	        if (!transaction->response_domain_recorded)
   336	            parse_query_payload(*transaction, transaction->response_body.data(),
   337	                transaction->response_body.size(), false, body_event->is_last_piece(), flow);
   338	    }
   339	}
