   347	void DohInspector::parse_query_payload(DohTransactionState& transaction,
   348	    const uint8_t* data, size_t length, bool from_client, bool last_piece, Flow* flow)
   349	{
   350	    if (!data or length < doh::DNS_HEADER_LEN)
   351	    {
   352	        if (last_piece and length)
   353	        {
   354	            bool& recorded = from_client ? transaction.request_domain_recorded :
   355	                transaction.response_domain_recorded;
   356	            recorded = true;
   357	            doh_stats.malformed_payloads++;
   358	        }
   359	        return;
   360	    }
   361	
   362	    doh::DnsQuestion question;
   363	    const doh::ParseStatus status = doh::parse_dns_question(data, length, question);
   364	    if (status == doh::ParseStatus::NEED_MORE_DATA)
   365	    {
   366	        if (last_piece)
   367	        {
   368	            bool& recorded = from_client ? transaction.request_domain_recorded :
   369	                transaction.response_domain_recorded;
   370	            recorded = true;
   371	            doh_stats.malformed_payloads++;
   372	        }
   373	        return;
   374	    }
   375	
   376	    bool& recorded = from_client ? transaction.request_domain_recorded :
   377	        transaction.response_domain_recorded;
   378	
   379	    if (status == doh::ParseStatus::MALFORMED)
   380	    {
